{"cards": [{"node_code": "N_aa15dca824a2c97f", "definition": "指管道运输系统中用于传输语音、数据及控制信号的专用通信设施、网络架构及信号传输技术。", "boundary": "本节点聚焦于管道沿线及站场的通信基础设施与信号传输。边界在于区分“通信设备”与“自动控制系统”：前者侧重信息传输通道（如光缆、微波、载波）及通信协议；后者侧重基于通信数据的逻辑判断、执行控制及闭环管理。若内容涉及通信硬件选型、线路敷设或通信网络拓扑，归入本节点；若涉及SCADA系统逻辑或控制算法，归入自动控制系统。", "includes": ["管道专用通信网络（光纤、微波、电力载波等）", "通信线路敷设、中继设备、交换设备及信号传输技术", "通信系统的工程设计、施工规范及维护管理"], "excludes": ["基于通信数据的自动控制逻辑、SCADA系统架构及控制算法（归入自动控制系统）", "通用民用通信网络建设（非管道专用）"], "sibling_distinctions": [{"other_code": "N_79dd256c8ad67753", "rule": "本节点关注信息的“传输”与“通道”建设；自动控制系统关注信息的“处理”、“决策”与“执行”控制。"}, {"other_code": "N_da81833e12314275", "rule": "本节点关注通信信号传输设备；辅助建筑物与设备关注站场土建、办公生活设施及非通信类公用工程。"}], "cross_boundary_rule": "涉及通信与控制的集成系统时，若侧重通信链路稳定性、带宽及信号质量，归入本节点；若侧重控制指令下发、状态反馈及逻辑联锁，归入自动控制系统。"}, {"node_code": "N_79dd256c8ad67753", "definition": "指管道运输系统中用于监测运行状态、执行调度指令、实现远程监控与自动化管理的控制系统及软件技术。", "boundary": "本节点聚焦于管道运行的“大脑”与“神经中枢”，即控制逻辑与执行管理。边界在于区分“自动控制系统”与“通信设备”：前者侧重SCADA系统、DCS、PLC等控制架构、控制算法及人机交互界面；后者侧重底层信号传输通道。若内容涉及调度中心软件、压力流量控制策略、报警联锁逻辑，归入本节点；若涉及光缆铺设或通信基站建设，归入通信设备。", "includes": ["SCADA（数据采集与监视控制）系统架构与功能", "管道运行调度、压力/流量自动控制策略及联锁保护逻辑", "站场就地控制系统（PLC/DCS）及人机交互界面设计"], "excludes": ["通信线路、光缆、微波等信号传输基础设施（归入通信设备）", "管道本体结构、阀门泵体等机械设备的物理设计（归入管道结构与设计）"], "sibling_distinctions": [{"other_code": "N_aa15dca824a2c97f", "rule": "本节点关注信息的“处理”、“决策”与“控制执行”；通信设备关注信息的“传输”与“通道”建设。"}, {"other_code": "N_53dc3cd8ad9fd359", "rule": "本节点关注控制系统的逻辑与软件；站场工程关注站场的土建布局、工艺管道布置及设备物理安装。"}], "cross_boundary_rule": "涉及站场控制室建设时，若侧重控制柜布置、电缆桥架及系统接口，归入站场工程；若侧重控制软件功能、控制逻辑及调度策略，归入本节点。"}]}
